import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Home, FileText, Settings, HelpCircle } from 'lucide-react';
import { cn } from '../../lib/utils';

const Sidebar = () => {
  const location = useLocation();

  const navigation = [
    {
      name: 'Dashboard',
      href: '/',
      icon: Home,
    },
    {
      name: 'Processes',
      href: '/',
      icon: FileText,
    },
    {
      name: 'Settings',
      href: '/settings',
      icon: Settings,
    },
    {
      name: 'Help',
      href: '/help',
      icon: HelpCircle,
    },
  ];

  return (
    <div className="flex h-full w-64 flex-col bg-background border-r">
      {/* Logo Section */}
      <div className="flex h-16 items-center px-6 border-b">
        <div className="flex items-center space-x-3">
          {/* Logo Placeholder */}
          <div className="h-8 w-8 rounded-lg bg-primary flex items-center justify-center">
            <span className="text-primary-foreground font-bold text-sm">KT</span>
          </div>
          <div>
            <h1 className="text-xl font-bold text-foreground">Know Transfer</h1>
            <p className="text-xs text-muted-foreground">Knowledge Management</p>
          </div>
        </div>
      </div>

      {/* Navigation */}
      <nav className="flex-1 px-4 py-6 space-y-2">
        {navigation.map((item) => {
          const isActive = location.pathname === item.href;
          return (
            <Link
              key={item.name}
              to={item.href}
              className={cn(
                'flex items-center space-x-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors',
                isActive
                  ? 'bg-primary text-primary-foreground'
                  : 'text-muted-foreground hover:text-foreground hover:bg-accent'
              )}
            >
              <item.icon className="h-5 w-5" />
              <span>{item.name}</span>
            </Link>
          );
        })}
      </nav>

      {/* Footer */}
      <div className="border-t px-4 py-4">
        <div className="text-xs text-muted-foreground">
          <p>Version 1.0.0</p>
          <p className="mt-1">© 2024 Know Transfer</p>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;
